<?php
require_once __DIR__.'/../../app/manager.php';
$db=app_db();
manager_install($db);
$demoPasswords=[];
foreach($db->query('SELECT email,password_encrypted FROM manager_demos')->fetch_all(MYSQLI_ASSOC) as $demoRow){
    try{$demoPasswords[strtolower((string)$demoRow['email'])]=manager_demo_decrypt_password((string)($demoRow['password_encrypted']??''));}
    catch(Throwable $e){error_log('admin demo password view: '.$e->getMessage());}
}
$users=$db->query("SELECT id,nome,email,telefone,saldo,depositou,indicados,plano,cpa,comissaofake,afiliado_ativo,bloc,demo,data_cadastro,total_apostado FROM appconfig ORDER BY CAST(id AS UNSIGNED) DESC LIMIT 1000")->fetch_all(MYSQLI_ASSOC);
foreach($users as &$user)$user['demo_password']=$user['demo']==='1'?($demoPasswords[strtolower((string)$user['email'])]??''):'';unset($user);
$summary=$db->query("SELECT COUNT(*) total,SUM(CASE WHEN demo='1' THEN 1 ELSE 0 END) demos,COALESCE(SUM(CAST(saldo AS DECIMAL(14,2))),0) balance,COALESCE(SUM(CAST(depositou AS DECIMAL(14,2))),0) deposits FROM appconfig")->fetch_assoc();
$notice=$_SESSION['admin_notice']??'';unset($_SESSION['admin_notice']);
$money=static fn($value):string=>'R$ '.number_format((float)($value?:0),2,',','.');
?>
