<section class="usr-stats"><article><span>USUÁRIOS</span><strong><?=number_format((int)$summary['total'],0,',','.')?></strong><small>Contas cadastradas</small></article><article><span>CONTAS DEMO</span><strong><?=number_format((int)$summary['demos'],0,',','.')?></strong><small>Acessos de treinamento</small></article><article><span>SALDO TOTAL</span><strong><?=$money($summary['balance'])?></strong><small>Saldo disponível nas contas</small></article><article><span>DEPÓSITOS</span><strong><?=$money($summary['deposits'])?></strong><small>Volume registrado</small></article></section>
