<?php if(!$users):?><div class="usr-empty">Nenhum usuário cadastrado.</div><?php else:?><div class="usr-table-wrap"><table><thead><tr><th>Usuário</th><th>Tipo</th><th>Saldo</th><th>Depositado</th><th>Cadastro</th><th>Status</th><th>Ações</th></tr></thead><tbody id="userRows"><?php foreach($users as $user):$blocked=in_array(strtolower((string)$user['bloc']),['1','true','on'],true);$name=trim((string)$user['nome'])?:explode('@',(string)$user['email'])[0];?><tr data-search="<?=app_escape(strtolower($name.' '.$user['email'].' '.$user['telefone']))?>" data-kind="<?=$user['demo']==='1'?'demo':'real'?>" data-blocked="<?=$blocked?'1':'0'?>"><td><div class="usr-person"><span><?=strtoupper(app_escape(substr($name,0,1)))?></span><div><strong><?=app_escape($name)?></strong><small><?=app_escape($user['telefone']?:'Telefone não informado')?></small></div></div></td><td><span class="usr-badge <?=$user['demo']==='1'?'demo':'real'?>"><?=$user['demo']==='1'?'Demo':'Usuário'?></span></td><td><b class="usr-money"><?=$money($user['saldo'])?></b></td><td><?=$money($user['depositou'])?></td><td><?=app_escape($user['data_cadastro']?:'Não informado')?></td><td><span class="usr-status <?=$blocked?'blocked':'active'?>"><i></i><?=$blocked?'Bloqueado':'Ativo'?></span></td><td><button class="usr-edit" type="button" data-user='<?=app_escape(json_encode($user,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT))?>'><?=ui_icon('edit')?> Visualizar e editar</button></td></tr><?php endforeach;?></tbody></table></div><div class="usr-empty" id="noResults" hidden>Nenhuma conta encontrada com este filtro.</div><?php endif;?></section>
